async function handleListConversations(
  ws: WebSocket,
  session: ChatSession,
  message: import('../../types/messages.js').ListConversationsMessage,
  options?: MessageHandlerOptions
): Promise<void> {
  if (!options?.history?.enabled || !options?.sessionStore?.listFor) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation history is not enabled or supported by the store');
    return;
  }

  try {
    const summaries = await options.sessionStore.listFor(session.userId, {
      limit: message.limit,
      before: message.before,
    });

    // ConversationSummary interface requires string properties for createdAt and updatedAt
    const conversations = summaries.map(s => ({
      sessionId: s.sessionId,
      createdAt: typeof s.createdAt === 'string' ? s.createdAt : s.createdAt.toISOString(),
      updatedAt: typeof s.updatedAt === 'string' ? s.updatedAt : s.updatedAt.toISOString(),
      entryCount: s.entryCount,
    }));

    ws.send(JSON.stringify({type: 'conversation_list', conversations}));
  } catch (error) {
    if (error instanceof StoreCannotList) {
      sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation history is not supported by the store configuration');
      return;
    }
    const errMessage = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'failed to list conversations', {error: errMessage, sessionId: session.sessionId});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to retrieve conversations');
  }
}

