it('answers UNSUPPORTED when history is disabled or the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws', async () => {
  const inner = new InMemorySessionStore();
  const storeWithNoListFor = delegatingTo(inner);
  const storeWithListFor = { ...storeWithNoListFor, listFor: () => Promise.resolve([]) };

  const disabledHistory = await startEngine(storeWithListFor, 'u1', undefined);
  const withoutList = await startEngine(storeWithNoListFor, 'u1', {enabled: true});
  const failingList = await startEngine({
    ...storeWithNoListFor,
    listFor: () => Promise.reject(new Error('database offline')),
  }, 'u1', {enabled: true});

  // We expect StoreCannotList to exist because we exported it. We just require it directly here or just instantiate it.
  const {StoreCannotList} = await import('../../infrastructure/stores/errors.js');
  const storeMisconfigured = await startEngine({
    ...storeWithNoListFor,
    listFor: () => Promise.reject(new StoreCannotList('cannot list')),
  }, 'u1', {enabled: true});

  const disabled = await askAfterConnect(disabledHistory, {type: 'list_conversations'});
  const unimplemented = await askAfterConnect(withoutList, {type: 'list_conversations'});
  const misconfigured = await askAfterConnect(storeMisconfigured, {type: 'list_conversations'});
  const failed = await askAfterConnect(failingList, {type: 'list_conversations'});

  expect({
    disabled: disabled.frames.map(frame => ({type: frame.type, code: frame.code})),
    unimplemented: unimplemented.frames.map(frame => ({type: frame.type, code: frame.code})),
    misconfigured: misconfigured.frames.map(frame => ({type: frame.type, code: frame.code})),
    failed: failed.frames.map(frame => ({type: frame.type, code: frame.code})),
    logged: logLines.filter(line => line.level === 'error' && line.category === 'ws'),
  }).toEqual({
    disabled: [{type: 'error', code: 'UNSUPPORTED'}],
    unimplemented: [{type: 'error', code: 'UNSUPPORTED'}],
    misconfigured: [{type: 'error', code: 'UNSUPPORTED'}],
    failed: [{type: 'error', code: 'SERVER_ERROR'}],
    logged: [
      expect.objectContaining({message: expect.stringContaining('database offline')}),
    ],
  });
});

